PUNCT = '.,?!'

def words(text):
    # lowercase, split on spaces, strip . , ? ! from both ends of each word
    out = set()
    for w in text.lower().split():
        w = w.strip(PUNCT)
        if w:
            out.add(w)
    return out

def solution(docs, query, user_groups, k):
    q = words(query)                  # a set: duplicate query words count once
    allowed = set(user_groups)
    scored = []
    for doc in docs:
        # access control first: a doc the user cannot see is never scored
        if not allowed & set(doc['groups']):
            continue
        score = len(q & words(doc['text']))
        if score > 0:
            scored.append((-score, doc['id']))   # sorts by score desc, then id asc
    scored.sort()
    return [doc_id for _, doc_id in scored[:k]]

