def solution(docs, query, user_groups, k):
    # Plain loops and lists: clean every word, compare one by one, then pick the best k by hand.
    def clean(text):
        result = []
        for w in text.lower().split():
            w = w.strip('.,?!')
            if w != '':
                result.append(w)
        return result
    q = []
    for w in clean(query):
        if w not in q:
            q.append(w)
    rows = []
    for doc in docs:
        ok = False
        for g in doc['groups']:
            if g in user_groups:
                ok = True
        if not ok:
            continue
        doc_words = clean(doc['text'])
        score = 0
        for w in q:
            if w in doc_words:
                score += 1
        if score > 0:
            rows.append([score, doc['id']])
    picked = []
    while rows and len(picked) < k:
        best = rows[0]
        for row in rows:
            if row[0] > best[0] or (row[0] == best[0] and row[1] < best[1]):
                best = row
        picked.append(best[1])
        rows.remove(best)
    return picked
